const int N=210;
const int M=21000;

struct Edge {
    int v,w;
};

vector<int> adj[M];
Edge edges[M];
int head[N],e;

void addEdge(int u,int v,int w){
    edges[e]={v,w};
    adj[u].push_back(e++);
    edges[e]={u,0};
    adj[v].push_back(e++);
}

int S,T;
int dist[N],q[N*2],arc[N],gap[N],inq[N],pre[N];

int maxFlow(int s,int t){
    memset(arc,-1,sizeof(arc));
    memset(pre,-1,sizeof(pre));
    int front=0,rear=0;
    q[rear++]=t; inq[t]=1; gap[0]++;
    dist[t]=0;
    while(front<rear){
        int u=q[front++];
        for(auto i:adj[u]){
            int v=edges[i].v;
            if(!inq[v]){
                q[rear++]=v;
                inq[v]=1;
                dist[v]=dist[u]+1;
                gap[dist[v]]++;
                arc[v]=i;
            }
        }
    }
    int total=0, u=s, low=INF;
    memset(pre,-1,sizeof(pre));
    pre[s]=s;
    while(dist[s]<t){
        bool pushed=false;
        for(int &i=arc[u];i!=-1;i=adj[u][i]){
            if(edges[i].w && dist[edges[i].v]+1==dist[u]){
                pushed=true;
                low=min(low,edges[i].w);
                pre[edges[i].v]=u;
                u=edges[i].v;
                if(u==t){
                    int delta=low;
                    while(u!=s){
                        int i=pre[u];
                        edges[i].w-=delta;
                        edges[i^1].w+=delta;
                        u=pre[u];
                    }
                    total+=delta;
                    low=INF;
                }
                break;
            }
        }
        if(pushed) continue;
        int minDist=t+1;
        for(auto i:adj[u]){
            int v=edges[i].v;
            if(edges[i].w && dist[v]<minDist){
                minDist=dist[v];
                arc[u]=i;
            }
        }
        gap[dist[u]]--;
        if(gap[dist[u]]==0) break;
        dist[u]=minDist+1;
        gap[dist[u]]++;
        u=pre[u];
    }
    return total;
}

