import java.util.*;
import java.io.*;

public class Main {
    static final int INF = 10000000;
    static final int N = 210;
    static final int M = 21000;

    static class Edge {
        int v, w;
        public Edge(int v, int w) {
            this.v = v; this.w = w;
        }
    }

    static List<Integer>[] adj = new ArrayList[M];
    static Edge[] edges = new Edge[M];
    static int[] head = new int[N];
    static int e;
    static int[] dist = new int[N];
    static int[] q = new int[N * 2];
    static int[] arc = new int[N];
    static int[] gap = new int[N];
    static int[] inq = new int[N];
    static int[] pre = new int[N];

    static char[][] grid1 = new char[12][12];
    static char[][] grid2 = new char[12][12];
    static int[][] sci = new int[12][12];
    static int[][] ca = new int[12][12];
    static int[][][] stone = new int[62][12][12];
    static int[][][][] dp = new int[62][12][12][12][12];
    static int[][] dir = {{-1,0},{1,0},{0,-1},{0,1}};
    static int n, t;

    public static void main(String[] args) throws IOException {
        for (int i = 0; i < M; i++) adj[i] = new ArrayList<>();

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        n = Integer.parseInt(parts[0]);
        t = Integer.parseInt(parts[1]);
        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                grid1[i][j] = line.charAt(j - 1);
            }
        }
        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                grid2[i][j] = line.charAt(j - 1);
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (grid1[i][j] == 'Z') stone[0][i][j] = 2;
                else if (grid1[i][j] == 'Y') stone[0][i][j] = 1;
                else {
                    sci[i][j] = grid1[i][j] - '0';
                }
            }
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n ; j++) {
                if (grid2[i][j] >= '0' && grid2[i][j] <= '9') {
                    ca[i][j] = grid2[i][j] - '0';
                }
            }
        }
        expand();

        boolean[][] visited = new boolean[12][12];

        for (int i=1; i<=n; ++i) {
            for (int j=1; j<=n; ++j) {
                if(sci[i][j] != 0) {
                    for (boolean[] row : new boolean[12]) Arrays.fill(row, false);
                    dfs(i, j, i, j, 0, visited);
                }
            }
        }
        for (int k=1; k<=t; ++k)
            for (int x=1; x<=n; ++x)
                for (int y=1; y<=n; ++y)
                    for (int nx=1; nx<=n; ++nx)
                        for(int ny=1; ny<=n; ++ny)
                            dp[k][x][y][nx][ny] += dp[k-1][x][y][nx][ny];

        int S = 0;
        int T = n * n * 2 + 1;

        for (int i = 0; i <= T; i++) {
            adj[i].clear();
        }
        for (int i=1; i<=n; ++i) {
            for (int j=1; j<=n; ++j) {
                addEdge(S, (i - 1) * n + j, sci[i][j]);
            }
        }
        for (int i=1; i<=n; ++i) {
            for (int j=1; j<=n; ++j) {
                addEdge(n * n + (i - 1) * n + j, T, ca[i][j]);
            }
        }
        for (int x=1; x<=n; ++x) {
            for (int y=1; y<=n; ++y) {
                for (int nx=1; nx<=n; ++nx) {
                    for (int ny=1; ny<=n; ++ny) {
                        if(sci[x][y] != 0 && ca[nx][ny] != 0) {
                            if(dp[t][x][y][nx][ny] != 0)
                                addEdge((x - 1) * n + y, n * n + (nx - 1) * n + ny, INF);
                        }
                    }
                }
            }
        }
        int ans = maxFlow(S, T);
        System.out.println(ans);
    }

    static void expand() {
        for (int k=1; k<=t; ++k)
            for (int i=1; i<=n; ++i)
                for (int j=1; j<=n; ++j) {
                    if(stone[k - 1][i][j] == 1)
                        stone[k][i][j] = 1;
                    else if(stone[k - 1][i][j]==2)
                        stone[k][i][j] = 2;
                    else {
                        for (int z=0; z<4; ++z) {
                            int nx = i + dir[z][0], ny = j + dir[z][1];
                            if (nx >= 1 && nx <= n && ny >=1 && ny <= n) {
                                if (stone[k-1][nx][ny] ==2)
                                    stone[k][i][j] = 2;
                            }
                        }
                    }
                }
    }

    static void dfs(int x,int y,int nowx,int nowy,int k, boolean[][] visited) {
        visited[nowx][nowy] = true;
        dp[k][x][y][nowx][nowy] = 1;
        if (k >= t || stone[k][nowx][nowy] != 0) return;
        for (int z=0; z<4; ++z){
            int nx=nowx+dir[z][0], ny=nowy+dir[z][1];
            if (nx>=1 && nx<=n && ny>=1 && ny<=n && !visited[nx][ny]){
                if(stone[k][nx][ny] != 0) continue;
                dfs(x,y,nx,ny,k+1, visited);
            }
        }
    }

    static void addEdge(int u, int v, int w) {
        edges[e] = new Edge(v, w);
        adj[u].add(e);
        e++;
        edges[e] = new Edge(u, 0);
        adj[v].add(e);
        e++;
    }

    static int maxFlow(int s, int t) {
        Arrays.fill(arc, -1);
        Arrays.fill(pre, -1);
        Arrays.fill(gap, 0);
        Arrays.fill(dist, 0);
        int front=0, rear=0;
        q[rear++]=t; inq[t]=1; gap[0]++;
        dist[t]=0;
        while(front<rear){
            int u=q[front++];
            for(int i:adj[u]){
                int v=edges[i].v;
                if(inq[v]==0){
                    q[rear++]=v;
                    inq[v]=1;
                    dist[v]=dist[u]+1;
                    gap[dist[v]]++;
                    arc[v]=i;
                }
            }
        }
        int total=0, u=s, low=INF;
        Arrays.fill(pre, -1);
        pre[s]=s;
        while (dist[s]<t) {
            boolean pushed=false;
            for (int i=arc[u]; i!=-1; i= (i==-1)? -1 : (i+1>=edges.length? -1 : i+1)) {
                if(i==-1) break;
                Edge e = edges[i];
                if(e.w>0 && dist[e.v]+1==dist[u]){
                    pushed=true;
                    low=Math.min(low, e.w);
                    pre[e.v]=u;
                    u=e.v;
                    if (u==t) {
                        int delta=low;
                        while (u!=s){
                            int i2= pre[u]==-1? -1 : pre[u];
                            for (int j :adj[i2]){
                                if (edges[j].v==u){
                                    edges[j].w-=delta;
                                    break;
                                }
                            }
                            for (int j :adj[u]){
                                if(edges[j].v==i2){
                                    edges[j].w+=delta;
                                    break;
                                }
                            }
                            u=pre[u];
                        }
                        total+=delta;
                        low=INF;
                    }
                    break;
                }
            }
            if(pushed) continue;
            int minDist=t+1;
            for(int i:adj[u]){
                if(edges[i].w>0 && dist[edges[i].v]<minDist){
                    minDist=dist[edges[i].v];
                    arc[u]=i;
                }
            }
            gap[dist[u]]--;
            if(gap[dist[u]]==0) break;
            dist[u]=minDist+1;
            gap[dist[u]]++;
            u=pre[u];
        }
        return total;
    }
}
